 class Task implements Callable<Object> {
    public static final int INF = 1 << 29;
    int n,c,m;
    int[] p,b;

    public Task(int n, int c, int m, int[] p, int[] b) {
        super();
        this.n = n;
        this.c = c;
        this.m = m;
        this.p = p;
        this.b = b;
    }

    int minW = 0;
    @Override
    public Object call() throws Exception {
        int[] count = new int[c];
        for(int i=0;i<m;i++) {
            count[b[i]-1]++;
        }
        for(int i=0;i<c;i++) {
            minW = Math.max(minW, count[i]);
        }
        Arrays.sort(p);
        int l = 0;
        int r = m;
        while(l + 1 < r) {
            int c = (l + r) / 2;
            if (promotions(c) < INF) {
                r = c;
            }else{
                l = c;
            }
        }
        return r + " " + promotions(r);
    }

    public int promotions(int w) {
        if (w < minW) return INF;
        int idx = m - 1;
        int promoted = 0;
        int promoting = 0;
        for(int row=n;row>=1;row--) {
            int count = 0;
            while(idx >= 0 && p[idx] > row) {
                promoted++;
                promoting++;
                idx--;
            }
            while(idx >= 0 && p[idx] == row) {
                if (count < w) {
                    count++;
                }else{
                    promoted++;
                    promoting++;
                }
                idx--;
            }
            if (count < w && promoting > 0) {
                int min = Math.min(w - count, promoting);
                promoting -= min;
            }
        }
        if (promoting > 0) {
            return INF;
        }
        return promoted;
    }

 }

