   private static void main2() throws IOException {
     char[] c = in.next().toCharArray();
     int n = c.length;
     char[] stack = new char[n];
     int idx = 0;
     int need = 0;
     for (int i = 0; i < n; i++) {
       if (idx > 0 && stack[idx-1] == c[i]) {
         idx--;
         continue;
       }
       if (i + idx >= n) {
         need++;
         idx--;
       } else {
         stack[idx++] = c[i];
       }
     }
     out.println((n-need)*5);
   }

