             for (int i = 0; i < N; i++) {
                 r[i] = getDouble();
                 c[i] = getDouble();
             }

             if (N == 1) {
                 double R = r[0];
                 double C = c[0];
                 if (C != X) {
                     return "IMPOSSIBLE";
                 }
                 return String.format("%.6f", V / R);
             }

             if (N == 2) {
                 double R1 = r[0];
                 double C1 = c[0];

                 double R2 = r[1];
