                     double time = V / (R1 + R2);
                     return String.format("%.6f", time);
                 }

                 if (C1 <= X && X <= C2) {
                     double k = (X - C1) / (C2 - C1);
                     double V1 = V * (1 - k);
                     double V2 = V * k;

                     double t1 = V1 / R1;
                     double t2 = V2 / R2;
                     return String.format("%.6f", Math.max(t1, t2));
                 } else {
                     return "IMPOSSIBLE";
                 }
             }

             return "not implemented";
         }
     }
