public class C_GCJ2017_Round1B {

     public static long MOD = 1000000007;
     static double[] dp;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File(
                 "output.txt")));

         Scanner in = new Scanner();
         int T = in.nextInt();
         for (int z = 0; z < T; z++) {
             int n = in.nextInt();
             int q = in.nextInt();
             double[][] h = new double[n][2];
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < 2; j++) {
                     h[i][j] = in.nextInt();
                 }
             }
             double[][] map = new double[n][n];
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < n; j++) {
                     map[i][j] = in.nextInt();
                 }
             }
             dp = new double[n];
             Arrays.fill(dp, -2);
             for (int i = 0; i < q; i++) {
                 int u = in.nextInt() - 1;
                 int v = in.nextInt() - 1;
                 out.println("Case #" + (z + 1) + ": " + cal(u, map, h));
             }

         }
         out.close();
     }

     public static double cal(int index, double[][] map, double[][] h) {
         if (index + 1 == map.length) {
             return 0;
         }
         if (dp[index] != -2) {
             return dp[index];
         }
         double dist = 0;
         double result = -1;
         for (int i = index + 1; i < map.length; i++) {
             dist += map[i - 1][i];
             if (dist <= h[index][0]) {
                 double v = cal(i, map, h);
                 double time = (double) dist / h[index][1];
                 if (v != -1) {
                     if (result == -1 || (result > time + v)) {
                         result = time + v;
                     }
                 }
             }
         }
         return dp[index] = result;
     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

     public static boolean nextPer(int[] data) {
         int i = data.length - 1;
         while (i > 0 && data[i] < data[i - 1]) {
             i--;
         }
         if (i == 0) {
             return false;
         }
         int j = data.length - 1;
         while (data[j] < data[i - 1]) {
             j--;
         }
         int temp = data[i - 1];
         data[i - 1] = data[j];
         data[j] = temp;
         Arrays.sort(data, i, data.length);
         return true;
     }

     public static int digit(long n) {
         int result = 0;
         while (n > 0) {
             n /= 10;
             result++;
         }
         return result;
     }

     public static double dist(long a, long b, long x, long y) {
         double val = (b - a) * (b - a) + (x - y) * (x - y);
         val = Math.sqrt(val);
         double other = x * x + a * a;
         other = Math.sqrt(other);
         return val + other;

     }

     public static class Point implements Comparable<Point> {

         int x, y;

         public Point(int start, int end) {
             this.x = start;
             this.y = end;
         }

         @Override
         public int hashCode() {
             int hash = 5;
             hash = 47 * hash + this.x;
             hash = 47 * hash + this.y;
             return hash;
         }

         @Override
         public boolean equals(Object obj) {
             if (obj == null) {
                 return false;
             }
             if (getClass() != obj.getClass()) {
                 return false;
             }
             final Point other = (Point) obj;
             if (this.x != other.x) {
                 return false;
             }
             if (this.y != other.y) {
                 return false;
             }
             return true;
         }

         @Override
         public int compareTo(Point o) {
             return Integer.compare(x, o.x);
         }
     }

     public static class FT {

         long[] data;

         FT(int n) {
             data = new long[n];
         }

         public void update(int index, long value) {
             while (index < data.length) {
                 data[index] += value;
                 index += (index & (-index));
             }
         }

         public long get(int index) {
             long result = 0;
             while (index > 0) {
                 result += data[index];
                 index -= (index & (-index));
             }
             return result;

         }
     }

     public static long gcd(long a, long b) {
         if (b == 0) {
             return a;
         }
         return gcd(b, a % b);
     }

     public static long pow(long a, long b, long MOD) {
         if (b == 0) {
             return 1;
         }
         if (b == 1) {
             return a;
         }
         long val = pow(a, b / 2, MOD);
         if (b % 2 == 0) {
             return val * val % MOD;
         } else {
             return val * (val * a % MOD) % MOD;

         }
     }

     static class Scanner {

         BufferedReader br;
         StringTokenizer st;

         public Scanner() throws FileNotFoundException {


             br = new BufferedReader(new InputStreamReader(new FileInputStream(new File("C-small-attempt1.in"))));
         }

         public String next() {

             while (st == null || !st.hasMoreTokens()) {
                 try {
                     st = new StringTokenizer(br.readLine());
                 } catch (Exception e) {
                     throw new RuntimeException();
                 }
             }
             return st.nextToken();
         }

         public long nextLong() {
             return Long.parseLong(next());
         }

         public int nextInt() {
             return Integer.parseInt(next());
         }

         public double nextDouble() {
             return Double.parseDouble(next());
         }

         public String nextLine() {
             st = null;
             try {
                 return br.readLine();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }

         public boolean endLine() {
             try {
                 String next = br.readLine();
                 while (next != null && next.trim().isEmpty()) {
                     next = br.readLine();
                 }
                 if (next == null) {
                     return true;
                 }
                 st = new StringTokenizer(next);
                 return st.hasMoreTokens();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }
     }
 }
