public class C_GCJ2017_Qual {

     public static long MOD = 1000000007;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File(
                 "output.txt")));

         Scanner in = new Scanner();
         int t = in.nextInt();
         for (int z = 0; z < t; z++) {
             long n = in.nextInt();
             long k = in.nextInt();
             PriorityQueue<Gap> q = new PriorityQueue<>();
             q.add(new Gap(0, n - 1));
             long min = 0;
             long max = 0;
             for (int i = 0; i < k; i++) {
                 Gap g = q.poll();
                 long tmp = g.ed - g.st;
                 min = tmp / 2;
                 max = tmp - min;
                 long a = g.st + min;
                 if (a > g.st) {
                     q.add(new Gap(g.st, a - 1));
                 }
                 if (a < g.ed) {
                     q.add(new Gap(a + 1, g.ed));
                 }
             }
