     }

     static class Gap implements Comparable<Gap> {

         long st, ed;

         public Gap(long st, long end) {
             this.st = st;
             this.ed = end;
         }

         @Override
         public int compareTo(Gap o) {
             long a = ed - st;
             long b = o.ed - o.st;
             if (a != b) {
                 return Long.compare(b, a);
             } else {
                 return Long.compare(st, o.st);
             }
         }

     }

