public class B {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int R = in.nextInt(), C = in.nextInt();
            int n = in.nextInt();

            PriorityQueue<Integer> pq_odd = new PriorityQueue<Integer>();
            PriorityQueue<Integer> pq_even = new PriorityQueue<Integer>();

            int evenN = n, oddN = n;
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    int cnt = 0;
                    if (i > 0) cnt++;
                    if (i < R - 1) cnt++;
                    if (j > 0) cnt++;
                    if (j < C - 1) cnt++;

                    if ((i + j) % 2 == 0) {
                        pq_odd.add(cnt);
                        evenN--;
                    } else {
                        pq_even.add(cnt);
                        oddN--;
                    }
                }
            }

            int minO = 0, minE = 0;



            while (oddN > 0) {
                oddN--;
                minO += pq_odd.poll();
            }

            while (evenN > 0) {
                evenN--;
                minE += pq_even.poll();
            }

            System.out.println("Case #" + caseN + ": " + Math.min(minO, minE));
        }
        out.close();
    }

