        }else{
            double min = Double.POSITIVE_INFINITY;
            for(int i = 0;i < n;i++){
                if(x == c[i]){
                    min = Math.min(min, (double)v/r[i]);
                }
            }
            if(x == c[0] && x == c[1]){
                min = Math.min(min, (double)v/(r[0]+r[1]));
            }





            for(int i = 0;i < n;i++){
                for(int j = 0;j < n;j++){
                    if(i == j)continue;
                    if(c[i] < x && x < c[j]){

                        double vr = (double)(x-c[i])/(c[j]-x);
                        double ni = (double)v/(1+vr)*1;
                        double nj = (double)v/(1+vr)*vr;
                        min = Math.min(min, Math.max(ni/r[i], nj/r[j]));
                    }
                }
            }
            if(Double.isInfinite(min)){
                out.println("IMPOSSIBLE");
            }else{
                out.printf("%.12f\n", min);
            }
        }
    }

    public static void preprocess()
    {
    }

    Scanner in;
    PrintWriter out;
    StringWriter sw;
    int cas;
    static List<Status> running = new ArrayList<Status>();

    @Override
    public void run()
    {
        long S = System.nanoTime();

        synchronized(running){
            Status st = new Status();
            st.id = cas;
            st.S = S;
            running.add(st);
        }
        process();

        synchronized(running){
            for(Status st : running){
                if(st.id == cas){
                    running.remove(st);
                    break;
                }
            }
        }
        long G = System.nanoTime();

        if(PROD){
            System.err.println("case " + cas + " solved. [" + (G-S)/1000000 + "ms]");
            synchronized(running){
                StringBuilder sb = new StringBuilder("running : ");
                for(Status st : running){
                    sb.append(st.id + ":" + (G-st.S)/1000000 + "ms, ");
                }
                System.err.println(sb);
            }
        }
    }

    private static class Status {
        public int id;
        public long S;
    }

    public B(int cas, Scanner in)
    {
        this.cas = cas;
