     private static String solve(int x, int r, int c) {
         if (r > c) {
             return solve(x, c, r);
         }
         if (x >= 7) {
             return NG;
         }
         if ((r * c) % x != 0) {
             return NG;
         }
         switch (x) {
             case 1:
             case 2:
                 return OK;

             case 3:
                 return solve3(r, c);

             case 4:
                 return solve4(r, c);
         }
         return NG;
     }

     private static String solve3(int r, int c) {
         if (r == 1) {
             return NG;
         }
         return OK;
     }

     private static String solve4(int r, int c) {
         if (r <= 2) {
             return NG;
         }
         return OK;
     }

