 class TaskA {
     int ans = Integer.MAX_VALUE;
     boolean grid[][];
     int R, C, N;

     public void solve(int testNumber, InputReader in, PrintWriter out) {
         R = in.nextInt();
         C = in.nextInt();
         N = in.nextInt();
         ans = Integer.MAX_VALUE;
         grid = new boolean[R + 2][C + 2];
         find(1, 1, N);
         out.println("Case #" + testNumber + ": " + ans);
     }

     private int find(int x, int y, int n) {
         if (n == 0) {
             ans = Math.min(ans, compute());
             return 0;
         }
         if (y == C + 1) {
             return find(x + 1, 1, n);
         }
         if (x == R + 1) {
             return 0;
         }

         grid[x][y] = false;
         find(x, y + 1, n);
         grid[x][y] = true;
         find(x, y + 1, n - 1);
         return 0;
     }

     private int compute() {
         int ans = 0;
         for (int i = 1; i <= R; i++) {
             for (int j = 1; j <= C; j++) {
                 if (grid[i][j]) {
                     if (grid[i - 1][j]) ans++;
                     if (grid[i][j - 1]) ans++;
                 }
             }
         }
         return ans;
     }

 }

