            if(1L << (n - 2) < M) {
                out.println("IMPOSSIBLE");
                return;
            }
            long[] way = new long[n];
            String[] res = new String[n];
            way[n-1] = 1;
            res[n-1] = "";
            for(int i = 0; i < n; i++) res[n-1] += "0";
            for(int i = n - 2; i >= 0; i--) {
                long m = M;
                res[i] = "";
                for(int j = 0; j <= i; j++) res[i] += "0";
                for(int j = i + 1; j < n; j++) {
                    if(m >= way[j]) {
                        way[i] += way[j];
                        m -= way[j];
                        res[i] += "1";
                    } else {
                        res[i] += "0";
                    }
                }
            }
            out.println("POSSIBLE");
            for(String s : res) out.println(s);
        }


