        int n = nextInt();
        int d = nextInt();


        long a[] = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }











        for (int i = 2 * d; i < n; i++) {
            if (a[i] != a[i % (2 * d)]) {
                printCase();
                out.println("CHEATERS!");
                return;
            }
        }
        long ans = 0;
        long cnts[] = new long[2 * d];
        while (true) {
            for (int i = 0; i < 2 * d; i++) {
                long dCur = a[(i + d) % (2 * d)] - a[i];
                long dPrev = a[(i + d - 1) % (2 * d)] - a[(i + 2 * d - 1) % (2 * d)];





                cnts[i] = max((dCur - dPrev) / 2, 0);

                if (cnts[i] > 0) {
                    ++ans;
                }
            }
            long csum = 0;
            for (int i = d; i < 2 * d; i++) {
                csum += cnts[i];
            }
            for (int i = 0; i < 2 * d; i++) {
                csum += cnts[i];
                csum -= cnts[(i + d) % (2 * d)];
                a[i] += csum;
            }
            for (int i = 0; i < d; i++) {
                if (a[i] != a[i + d]) {
                    printCase();
                    out.println("CHEATERS!");
                    return;
                }
            }
            if (d == 1) {
                break;
            }
            d /= 2;
        }
        printCase();
        out.println(ans);



