        Set<Integer> digits = new HashSet<>();
        for (int i = 0; i < 1000; i++) {
            int k = n + i * n;
            while(k > 0) {
                digits.add(k % 10);
                k/=10;
            }

            if (digits.size() >= 10) {
                return n + i * n;
            }
        }
        return -1;
    }

