            String s = br.readLine();
            int count = 0;
            while(true) {
                char c = s.charAt(0);
                int n = s.length();
                int i = 1;
                while(i < n) {
                    if (s.charAt(i) == c)i++;
                    else break;
                }
                if (i == n && c == '+')break;

                String tail = s.substring(i);
                for (int j = 0; j < i; j++) {
                    if (s.charAt(j) == '+')tail = "-" + tail;
                    else tail = "+" + tail;
                }

                s = tail;
                count++;

            }
            System.out.println("Case #" + ind + ": " + count);
        }


    }

