    String calc(int N) {
        if (N == 0) return "INSOMNIA";
        int d = 0;
        for (int res = N ;; res += N) {
            for (int i = res ; i > 0 ; i /= 10) {
                d |= 1 << (i % 10);
            }
            if (d == (1 << 10) - 1) return Integer.toString(res);
        }
    }

