             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified())
                     toRun = candidate;
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("a.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskA solver = new TaskA();
         int testCount = Integer.parseInt(in.next());
         for (int i = 1; i <= testCount; i++)
             solver.solve(i, in, out);
         out.close();
     }

     static class TaskA {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printFormat("Case #%d:\n", testNumber);
             int n = in.readInt();
             int m = in.readInt();
             char[][] a = IOUtils.readTable(in, n, m);
             boolean[] containsLetters = new boolean[n];
             for (int r = 0; r < n; r++) {
                 int lastFilledCol = -1;
                 for (int c = 0; c < m; c++) {
                     if (Character.isLetter(a[r][c])) {
                         containsLetters[r] = true;
                         fill(a[r], lastFilledCol + 1, c - 1, a[r][c]);
                         lastFilledCol = c;
                     }
                 }
                 if (containsLetters[r]) {
                     fill(a[r], lastFilledCol + 1, m - 1, a[r][lastFilledCol]);
                 }
             }
             boolean wasCopied = false;
             int lastFilledRow = -1;
             for (int r = 0; r < n; r++) {
                 if (containsLetters[r]) {
                     wasCopied = true;
                     copy(a, lastFilledRow + 1, r - 1, a[r]);
                     lastFilledRow = r;
                 }
             }
             if (!wasCopied) {
                 throw new AssertionError();
             }
             copy(a, lastFilledRow + 1, n - 1, a[lastFilledRow]);
             for (char[] row : a) {
                 for (char c : row) {
                     if (!Character.isLetter(c)) {
                         throw new AssertionError();
                     }
                 }
             }
             IOUtils.printTable(out, a);
         }

         private void copy(char[][] table, int top, int bottom, char[] arr) {
             for (int i = top; i <= bottom; i++) {

                 for (int j = 0; j < arr.length; j++) {
                     table[i][j] = arr[j];
                 }
             }
         }

         private void fill(char[] arr, int L, int R, char ch) {
             for (int j = L; j <= R; j++) {
                 arr[j] = ch;
             }
         }

     }

     static class IOUtils {
         public static char[] readCharArray(InputReader in, int size) {
             char[] array = new char[size];
             for (int i = 0; i < size; i++) {
                 array[i] = in.readCharacter();
             }
             return array;
         }

         public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
             char[][] table = new char[rowCount][];
             for (int i = 0; i < rowCount; i++) {
                 table[i] = readCharArray(in, columnCount);
             }
             return table;
         }

         public static void printTable(OutputWriter out, char[][] table) {
             for (char[] row : table) {
                 out.printLine(new String(row));
             }
         }

     }

     static class OutputWriter {
         private final PrintWriter writer;

         public OutputWriter(OutputStream outputStream) {
             writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
         }

         public OutputWriter(Writer writer) {
             this.writer = new PrintWriter(writer);
         }

         public void print(Object... objects) {
             for (int i = 0; i < objects.length; i++) {
                 if (i != 0) {
                     writer.print(' ');
                 }
                 writer.print(objects[i]);
             }
         }

         public void printLine(Object... objects) {
             print(objects);
             writer.println();
         }

         public void printFormat(String format, Object... objects) {
             writer.printf(format, objects);
         }

         public void close() {
             writer.close();
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public String readString() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             StringBuilder res = new StringBuilder();
             do {
                 if (Character.isValidCodePoint(c)) {
                     res.appendCodePoint(c);
                 }
                 c = read();
             } while (!isSpaceChar(c));
             return res.toString();
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public char readCharacter() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             return (char) c;
         }

         public String next() {
             return readString();
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }
 }

