 class TaskD {
     final static String WIN = "GABRIEL";
     final static String FAIL = "RICHARD";

     public void solve(int testNumber, InputReader in, OutputWriter out) {
         out.printFormat("Case #%d: ", testNumber);
         int x = in.readInt();
         int a = in.readInt();
         int b = in.readInt();
         if (a > b) {
             int t = a; a = b; b = t;
         }

         if (a == 1 && b == 1) {
             out.printLine(x == 1 ? WIN : FAIL);
             return;
         }
         if (a == 1 && b == 2) {
             out.printLine(x == 1 || x == 2 ? WIN : FAIL);
             return;
         }
         if (a == 1 && b == 3) {
             out.printLine(x == 1 ? WIN : FAIL);
             return;
         }
         if (a == 1 && b == 4) {
             out.printLine(x == 1 || x == 2 ? WIN : FAIL);
             return;
         }

         if (a == 2 && b == 2) {
             out.printLine(x == 1 || x == 2 ? WIN : FAIL);
             return;
         }
         if (a == 2 && b == 3) {
             out.printLine(x == 1 || x == 2 || x == 3 ? WIN : FAIL);
             return;
         }
         if (a == 2 && b == 4) {
             out.printLine(x == 1 || x == 2 ? WIN : FAIL);
             return;
         }

         if (a == 3 && b == 3) {
             out.printLine(x == 1 || x == 3 ? WIN : FAIL);
             return;
         }
         if (a == 3 && b == 4) {
             out.printLine(x == 1 || x == 2 || x == 3 || x == 4 ? WIN : FAIL);
             return;
         }

         if (a == 4 && b == 4) {
             out.printLine(x == 1 || x == 2 || x == 4 ? WIN : FAIL);
             return;
         }

         throw new IllegalArgumentException();
     }
 }

 class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

