 class TaskB {
     int maxB = 0;
     int total = 0;
     int sum = 0;

     public void solve(int testNumber, InputReader in, OutputWriter out) {
         out.printFormat("Case #%d: ", testNumber);
         int k = in.readInt();
         int len = in.readInt();
         int n = in.readInt();
         char[] keys = in.readString().toCharArray();
         char[] target = in.readString().toCharArray();
         maxB = total = sum = 0;
         brute(new StringBuilder(), keys, target, n);
         out.printFormat("%.15f\n", maxB - (double)sum / total);
     }

     private void brute(StringBuilder s, char[] keys, char[] target, int n) {
         if (s.length() == n) {
             total++;
             int cnt = 0;
             for (int start = 0; start + target.length <= n; start++) {
                 boolean ok = true;
                 for (int i = start, j = 0; j < target.length; i++, j++) {
                     if (s.charAt(i) != target[j]) {
                         ok = false;
                         break;
                     }
                 }
                 if (ok) cnt++;
             }
             sum += cnt;
             maxB = Math.max(maxB, cnt);
             return;
         }
         for (char c : keys) {
             s.append(c);
             brute(s, keys, target, n);
             s.setLength(s.length() - 1);
         }
     }
 }

 class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c))
                res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public String next() {
        return readString();
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
 }

 class OutputWriter {
