     private long revNum(long x) {
    long ret=0;
    while (x>0) {
        ret *= 10;
        ret += x%10;
        x/=10;
    }
    return ret;
     }

     private long[] fR_Ret = new long[1000000+1];
     private long fR(long n) {
    long ret=0;
    if (n==1) {
        return 1;
    }
    if (fR_Ret[(int)n] != -1) {
        return fR_Ret[(int)n];
    }

    long min=n;
    long result1 = fR(n-1);
    if (result1+1<min) {
        min = result1+1;
    }
    long r1 = revNum(n);
    long r2 = revNum(r1);
    if (r2 == n && r1 < n) {
        long result2 = fR(r1);
        if (result2+1<min) {
        min = result2+1;
        }
    }
    fR_Ret[(int)n]=min;
    return min;
     }

     private void solve(long n) {
    long ans = fR(n);
    output(ans);
     }

