            for(int i = 0; i < N; i++){
                for(int j = 0; j < N; j++){
                    Ds[i][j] = sc.nextLong();
                }
            }
            for(int k = 0; k < N; k++){
                for(int i = 0; i < N; i++){
                    for(int j = 0; j < N; j++){
                        if(Ds[i][k] < 0 || Ds[k][j] < 0){ continue; }

                        if(Ds[i][j] < 0){
                            Ds[i][j] = Ds[i][k] + Ds[k][j];
                        }else{
                            Ds[i][j] = Math.min(Ds[i][j], Ds[i][k] + Ds[k][j]);
                        }
                    }
                }
            }

            double[][] time = new double[N][N];
            for(int i = 0; i < N; i++){
                for(int j = 0; j < N; j++){
