            for(int from = 0; from < N; from++){
                for(int to = 0; to < N; to++){
                    if(from == to){ continue; }
                    if(Ds[from][to] < 0){ continue; }

                    if(Es[from] < Ds[from][to]){ continue; }
                    time[from][to] = Math.min(time[from][to], (double)(Ds[from][to]) / Ss[from]);
