       int tests = nextInt();

       for (int test = 1; test <= tests; test++) {
         int n = nextInt();
         int k = nextInt();

         boolean[] o = new boolean[n + 2];
         o[0] = o[n + 1] = true;

         int resMin = -1;
         int resMax = -1;
         for (int i = 0; i < k; i++) {
           int[] l = new int[n + 2];
           int curL = 0;
           for (int j = 0; j < n + 2; j++) {
             if (o[j]) {
               curL = 0;
             } else {
               l[j] = curL;
               curL++;
             }
           }

           int[] r = new int[n + 2];
           int curR = 0;
           for (int j = n + 1; j >= 0; j--) {
             if (o[j]) {
               curR = 0;
             } else {
               r[j] = curR;
               curR++;
             }
           }

           int p = -1;
           int min = -1;
           int max = -1;
           for (int j = 0; j < n + 2; j++) {
             if (!o[j]) {
               int jMin = Math.min(l[j], r[j]);
               int jMax = Math.max(l[j], r[j]);
               if (jMin > min || (jMin == min && jMax > max)) {
                 p = j;
                 min = jMin;
                 max = jMax;
               }
             }
           }
           o[p] = true;
           resMin = min;
           resMax = max;
