public class Main {
     public static void main(String[] args) {
         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "E-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified()) {
                     toRun = candidate;
                 }
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("e.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskE solver = new TaskE();
         solver.solve(1, in, out);
         out.close();
     }

     static class TaskE {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             int p = in.readInt();
             int[][] v = new int[p][];
             int[][] s = new int[p][];
             for (int i = 0; i < p; i++) {
                 int c = in.readInt();
                 v[i] = new int[c];
                 s[i] = new int[c];
                 IOUtils.readIntArrays(in, v[i], s[i]);
                 ArrayUtils.reverse(v[i]);
                 ArrayUtils.reverse(s[i]);
                 MiscUtils.decreaseByOne(v[i], s[i]);
             }

             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 int c;
                 int[] ids;


                 public void read(InputReader in) {
                     n = in.readInt();
                     c = in.readInt();
                     ids = IOUtils.readIntArray(in, n);
                 }

                 int[][] vv;
                 int[][] ss;
                 boolean answer;


                 public void solve() {
                     vv = new int[n][];
                     ss = new int[n][];
                     for (int i = 0; i < n; i++) {
                         vv[i] = v[ids[i]];
                         ss[i] = s[ids[i]];
                     }
                     TaskE.State start =
                             new TaskE.State(ArrayUtils.createArray(n, c - 1), ArrayUtils.createArray(4, -1), 0);
                     answer = go(start);
                 }

                 private boolean go(TaskE.State start) {
                     while (true) {
                         boolean updated = false;
