                N--;
            }
        }
        int [] r2 = {0, R-1, 0, R-1};
        int [] c2 = {0, 0, C-1, C-1};
        int ret=0;
        if(N>0)
        for(int d=0; d<4; d++)
        {
            if(!p[r2[d]][c2[d]])
            {
                p[r2[d]][c2[d]]=true;
                ret+=2;
                N--;
                if(N<=0)break;
            }
        }

        if(N>0)
            for(int c=0; c<C; c++)
            {
                if(!p[0][c])
                {
                    p[0][c]=true;
                    ret+=3;
                    N--;
                    if(N<=0)break;
                }
            }
        if(N>0)
            for(int c=0; c<C; c++)
            {
                if(!p[R-1][c])
                {
                    p[R-1][c]=true;
                    ret+=3;
                    N--;
                    if(N<=0)break;
                }
            }
        if(N>0)
            for(int r=0; r<R; r++)
            {
                if(!p[r][0])
                {
                    p[r][0]=true;
                    ret+=3;
                    N--;
                    if(N<=0)break;
                }
            }
        if(N>0)
            for(int r=0; r<R; r++)
            {
                if(!p[r][C-1])
                {
                    p[r][C-1]=true;
                    ret+=3;
                    N--;
                    if(N<=0)break;
                }
            }
        if(N>0)
            ret+=N*4;
        ret = Math.min(ret, ret2);
        return ""+ret;
    }

    private int solve2(int R, int C, int N) {

        boolean [] [] p = new boolean [R][C];
