            int a = 0, b = 0, maxEat = 0;
            for (int i = 1; i < arr.length; i++) {
                a += Math.max(0, arr[i - 1] - arr[i]);
                maxEat = Math.max(maxEat, arr[i - 1] - arr[i]);
